import java.util.Scanner;

public class Main {
    static final int MAX_LEVEL_COUNT = 18;
    static long[] precomputed = new long[MAX_LEVEL_COUNT];

    static long calculate(long number, int level) {
        int count = (int)(number / precomputed[level]);
        number %= precomputed[level];

        if (number == 0)
            return level * count;
        return level * count + Math.min(level + calculate(precomputed[level] - number, level - 1),
                                          calculate(number, level - 1));
    }

    public static void main(String[] args) {
        precomputed[0] = 0;
        for (int i = 1; i < MAX_LEVEL_COUNT; i++)
            precomputed[i] = precomputed[i - 1] * 10 + 1;

        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNextLong()) {
            long input_value = scanner.nextLong();
            System.out.println(calculate(input_value, MAX_LEVEL_COUNT - 1));
        }
        scanner.close();
    }
}
